import { crypto } from "node:crypto";

/**
 * Compare two strings in constant time for timing-safe equality comparison.
 * This is important for security-sensitive operations like password comparison
 * to prevent timing attacks.
 * 
 * Uses UTF-8 byte comparison (via TextEncoder) rather than UTF-16 code unit
 * comparison to ensure proper Unicode handling.
 * 
 * @param a - First string to compare
 * @param b - Second string to compare
 * @returns true if the strings are equal, false otherwise
 */
export function timingSafeEqual(a: string, b: string): boolean {
  // Use TextEncoder to convert strings to UTF-8 bytes
  const encoder = new TextEncoder();
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);

  // Constant-time comparison
  const result = crypto.timingSafeEqual(aBytes, bBytes);
  return result;
}

